(() => {
  const areas = window.FISO_DATA?.dangerAreas;
  const metadata = window.FISO_ENR_DA_METADATA ?? {};
  if (!areas) return;

  const metadataFields = [
    "name",
    "lower",
    "upper",
    "activity",
    "service",
    "contact",
    "authority",
    "hours",
    "officialRemarks",
    "enrBoundary",
    "enrText",
  ];

  for (const [id, entry] of Object.entries(metadata)) {
    const area = areas[id];
    if (!area || !entry) continue;

    for (const field of metadataFields) {
      const value = entry[field];
      if (value != null && String(value).trim()) {
        area[field] = value;
      }
    }

    area.enrSource = "UK AIP ENR 5.1";
  }
})();
